head.script:
scwin.trigger1_onclick = function(e) {
    dataMap1.setEmptyValue();
    dataMap2.setEmptyValue();
};
scwin.trigger2_onclick = function(e) {
    dataMap1.set("key1", "test");
    dataMap1.set("key2", "test");
    dataMap2.set("key1", "test");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 'input들의 값을 변경'버튼을 클릭 후 'setEmpty'버튼을 클릭한다.
    //1. After running the sample file, click the 'Change the values of inputs' button and click the 'setEmpty' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    // verify step 1. test값이 입력되어지고 defaultValue가 있는 경우에는 default1, default2값이 셋팅되고 defaultValue가 없는 경우에는 빈값 으로 셋팅되어진다.
    //1. If test value is input and defaultValue is set, default1 and default2 values are set. If defaultValue is not set, it is set to blank value.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue() == 'test'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input2').getValue() == 'test'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_11').getValue() == 'test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 'input들의 값을 변경'버튼을 클릭 후 'setEmpty'버튼을 클릭한다.
    //1. After running the sample file, click the 'Change the values of inputs' button and click the 'setEmpty' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // verify step 1. test값이 입력되어지고 defaultValue가 있는 경우에는 default1, default2값이 셋팅되고 defaultValue가 없는 경우에는 빈값 으로 셋팅되어진다.
    //1. If test value is input and defaultValue is set, default1 and default2 values are set. If defaultValue is not set, it is set to blank value.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue() == 'default1'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input2').getValue() == 'default2'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_11').getValue() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 19-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
